{
  "task_summary": "Predict whether a respondent has high blood pressure from BRFSS survey and health-behavior covariates.",
  "ranking": [
    {
      "rank": 1,
      "feature_id": 0,
      "rationale": "Age is a strong, stable clinical risk factor for hypertension across domains."
    },
    {
      "rank": 2,
      "feature_id": 10,
      "rationale": "Diabetes is tightly linked to hypertension and should generalize well as a medical risk marker."
    },
    {
      "rank": 3,
      "feature_id": 11,
      "rationale": "Poverty captures chronic socioeconomic risk that often remains predictive across states and years."
    },
    {
      "rank": 4,
      "feature_id": 15,
      "rationale": "Cost-related care avoidance reflects access barriers and health burden relevant to blood pressure."
    },
    {
      "rank": 5,
      "feature_id": 12,
      "rationale": "Employment status is a broad proxy for age, health, and socioeconomic stress with some cross-domain stability."
    },
    {
      "rank": 6,
      "feature_id": 17,
      "rationale": "Sex is a basic demographic predictor with persistent but moderate association to hypertension."
    },
    {
      "rank": 7,
      "feature_id": 16,
      "rationale": "Race can correlate with hypertension risk through structural factors, though it is a shortcut and may shift across domains."
    },
    {
      "rank": 8,
      "feature_id": 14,
      "rationale": "State may capture regional prevalence and policy differences, but it is also a strong domain identifier and can overfit."
    },
    {
      "rank": 9,
      "feature_id": 13,
      "rationale": "Survey year can absorb secular trends, but it is mainly a domain marker rather than a causal risk factor."
    },
    {
      "rank": 10,
      "feature_id": 5,
      "rationale": "Physical inactivity is a plausible and fairly stable behavioral risk factor for blood pressure."
    },
    {
      "rank": 11,
      "feature_id": 6,
      "rationale": "Lifetime smoking history is relevant to cardiovascular risk, though its direct link to hypertension is weaker."
    },
    {
      "rank": 12,
      "feature_id": 7,
      "rationale": "Current smoking status may help, but it is noisier and more behaviorally contingent than broader health factors."
    },
    {
      "rank": 13,
      "feature_id": 3,
      "rationale": "Alcohol intake can affect blood pressure, but self-report noise and nonlinear effects reduce reliability."
    },
    {
      "rank": 14,
      "feature_id": 4,
      "rationale": "Binge drinking is related to alcohol exposure, but it is a coarse and potentially unstable proxy."
    },
    {
      "rank": 15,
      "feature_id": 1,
      "rationale": "Fruit intake is a general health-behavior marker with only indirect association to hypertension."
    },
    {
      "rank": 16,
      "feature_id": 2,
      "rationale": "Vegetable intake is similarly indirect and likely weaker than core clinical or socioeconomic predictors."
    },
    {
      "rank": 17,
      "feature_id": 9,
      "rationale": "Other cancer history is unlikely to be a robust predictor and may mostly reflect age or healthcare utilization."
    },
    {
      "rank": 18,
      "feature_id": 8,
      "rationale": "Skin cancer history is the least relevant to blood pressure and may mainly act as an age or screening artifact."
    }
  ]
}
